import "pe"

rule SOC_RedLine_Sample_Set_Credential_Stealer
{
    meta:
        description = "Detects a confirmed credential-stealer sample set based on analyst-extracted indicators"
        author = "SOC Detection Engineering"
        date = "2026-08-01"
        scope = "Confirmed sample set only"
        attribution = "RedLine label reported for these samples; rule does not assert broader family attribution"
        reference = "Internal malware analysis"
        confidence = "high"

    strings:
        // Credential-access API observed in the confirmed samples.
        $api_crypt_unprotect = "CryptUnprotectData" ascii wide

        // SQLite API associated with access to browser credential databases.
        $api_sqlite_open = "sqlite3_open" ascii wide

    condition:
        // Require a valid PE file before evaluating PE-specific properties.
        uint16(0) == 0x5A4D and
        pe.is_pe and

        // Both analyst-extracted API strings must be present.
        all of ($api_*) and

        // Require the PE section layout observed in the confirmed sample set.
        // exact_name avoids matching section names that only share a prefix.
        for any section in pe.sections : (
            section.name == ".text"
        ) and
        for any section in pe.sections : (
            section.name == ".rdata"
        )
}
```

This rule intentionally anchors detection to the confirmed indicators and does not generalize attribution to all RedLine variants.

