import "pe"

/*
    Detects the confirmed credential-stealer sample set based only on
    analyst-extracted indicators. This rule must not be treated as broad
    RedLine family attribution without additional validation.
*/
rule CredentialStealer_RedLine_Confirmed_Sample_Set
{
    meta:
        description = "Detects a confirmed RedLine credential-stealer sample set using observed API strings and PE sections"
        author = "SOC Detection Engineering"
        date = "2026-08-01"
        version = "1.0"
        scope = "Confirmed sample set only"
        attribution = "No family-wide attribution; indicators are limited to the analyzed samples"
        confidence = "high for the confirmed sample set; unknown for other variants"
        reference = "Internal malware analysis"
        sample_hash = "REPLACE_WITH_CONFIRMED_SAMPLE_SHA256"

    strings:
        // Windows DPAPI function commonly used to decrypt stored credentials.
        $api_crypt_unprotect = "CryptUnprotectData" ascii

        // SQLite function consistent with accessing browser credential databases.
        $api_sqlite_open = "sqlite3_open" ascii

    condition:
        // Require a valid PE rather than matching the strings in arbitrary data.
        pe.is_pe and

        // Both analyst-observed strings must be present to reduce false positives.
        all of them and

        // Require the section layout observed in the confirmed samples.
        for any i in (0 .. pe.number_of_sections - 1) : (
            pe.sections[i].name == ".text"
        ) and
        for any i in (0 .. pe.number_of_sections - 1) : (
            pe.sections[i].name == ".rdata"
        )
}
