#!/usr/bin/env python3
"""
Detect common DNS-tunneling indicators in a PCAP using Scapy.

Indicators:
- Unusually long subdomain labels
- High query volume to one base domain
- High-entropy subdomain labels

Install:
    python3 -m pip install scapy

Usage:
    python3 dns_tunnel_detector.py capture.pcap
    python3 dns_tunnel_detector.py capture.pcap \
        --long-label 40 \
        --volume-threshold 100 \
        --entropy-threshold 3.5
"""

import argparse
import math
from collections import Counter, defaultdict
from typing import Dict, Iterable, List, Optional, Tuple

from scapy.all import DNS, DNSQR, IP, IPv6, PcapReader


def shannon_entropy(value: str) -> float:
    """Return Shannon entropy in bits per character."""
    if not value:
        return 0.0

    frequencies = Counter(value)
    length = len(value)

    return -sum(
        (count / length) * math.log2(count / length)
        for count in frequencies.values()
    )


def normalize_qname(qname: object) -> str:
    """Convert a Scapy DNS name to a normalized string."""
    if isinstance(qname, bytes):
        name = qname.decode("utf-8", errors="replace")
    else:
        name = str(qname)

    return name.rstrip(".").lower()


def get_base_domain(name: str, suffix_labels: int) -> str:
    """
    Approximate the registrable/base domain using the final N labels.

    The default of two works for names such as example.com but not every
    multi-label public suffix, such as example.co.uk. Use --suffix-labels 3
    when appropriate for the environment being analyzed.
    """
    labels = [label for label in name.split(".") if label]

    if len(labels) <= suffix_labels:
        return ".".join(labels)

    return ".".join(labels[-suffix_labels:])


def get_source_address(packet: object) -> str:
    if packet.haslayer(IP):
        return str(packet[IP].src)
    if packet.haslayer(IPv6):
        return str(packet[IPv6].src)
    return "unknown"


def iter_dns_questions(dns: DNS) -> Iterable[DNSQR]:
    """Iterate over DNS questions represented in a Scapy DNS packet."""
    question = dns.qd
    remaining = int(dns.qdcount or 0)

    while isinstance(question, DNSQR) and remaining > 0:
        yield question
        remaining -= 1
        question = question.payload


def analyze_capture(
    capture_path: str,
    long_label_threshold: int,
    volume_threshold: int,
    entropy_threshold: float,
    entropy_min_length: int,
    suffix_labels: int,
    max_examples: int,
) -> Tuple[int, Dict[str, int], Dict[str, dict]]:
    total_queries = 0
    domain_volumes: Counter = Counter()
    findings: Dict[str, dict] = defaultdict(
        lambda: {
            "query_count": 0,
            "long_label_count": 0,
            "high_entropy_count": 0,
            "long_label_examples": [],
            "high_entropy_examples": [],
            "sources": Counter(),
        }
    )

    with PcapReader(capture_path) as packets:
        for packet in packets:
            if not packet.haslayer(DNS):
                continue

            dns = packet[DNS]

            # qr=0 denotes a DNS query; qr=1 denotes a response.
            if int(dns.qr) != 0 or not dns.qd:
                continue

            source = get_source_address(packet)

            for question in iter_dns_questions(dns):
                qname = normalize_qname(question.qname)
                if not qname:
                    continue

                labels = [label for label in qname.split(".") if label]
                base_domain = get_base_domain(qname, suffix_labels)

                total_queries += 1
                domain_volumes[base_domain] += 1
                findings[base_domain]["query_count"] += 1
                findings[base_domain]["sources"][source] += 1

                # Analyze only labels before the assumed base-domain suffix.
                subdomain_labels = (
                    labels[:-suffix_labels]
                    if len(labels) > suffix_labels
                    else []
                )

                for label in subdomain_labels:
                    label_entropy = shannon_entropy(label)

                    if len(label) >= long_label_threshold:
                        findings[base_domain]["long_label_count"] += 1

                        examples: List[dict] = findings[base_domain][
                            "long_label_examples"
                        ]
                        if len(examples) < max_examples:
                            examples.append(
                                {
                                    "source": source,
                                    "query": qname,
                                    "label": label,
                                    "length": len(label),
                                }
                            )

                    if (
                        len(label) >= entropy_min_length
                        and label_entropy >= entropy_threshold
                    ):
                        findings[base_domain]["high_entropy_count"] += 1

                        examples = findings[base_domain][
                            "high_entropy_examples"
                        ]
                        if len(examples) < max_examples:
                            examples.append(
                                {
                                    "source": source,
                                    "query": qname,
                                    "label": label,
                                    "length": len(label),
                                    "entropy": round(label_entropy, 3),
                                }
                            )

    flagged = {}

    for domain, details in findings.items():
        reasons = []

        if domain_volumes[domain] >= volume_threshold:
            reasons.append(
                f"high query volume: {domain_volumes[domain]} queries"
            )

        if details["long_label_count"]:
            reasons.append(
                f"long labels: {details['long_label_count']} occurrences"
            )

        if details["high_entropy_count"]:
            reasons.append(
                "high-entropy labels: "
                f"{details['high_entropy_count']} occurrences"
            )

        if reasons:
            details["reasons"] = reasons
            flagged[domain] = details

    return total_queries, dict(domain_volumes), flagged


def print_report(
    total_queries: int,
    domain_volumes: Dict[str, int],
    flagged: Dict[str, dict],
) -> None:
    print("DNS tunneling indicator report")
    print("=" * 31)
    print(f"DNS queries analyzed: {total_queries}")
    print(f"Base domains observed: {len(domain_volumes)}")
    print(f"Base domains flagged:  {len(flagged)}")

    if not flagged:
        print("\nNo indicators exceeded the configured thresholds.")
        return

    for domain, details in sorted(
        flagged.items(),
        key=lambda item: item[1]["query_count"],
        reverse=True,
    ):
        print(f"\n[FLAGGED] {domain}")

        for reason in details["reasons"]:
            print(f"  Reason: {reason}")

        top_sources = details["sources"].most_common(5)
        if top_sources:
            sources = ", ".join(
                f"{source} ({count})" for source, count in top_sources
            )
            print(f"  Top sources: {sources}")

        if details["long_label_examples"]:
            print("  Long-label examples:")
            for example in details["long_label_examples"]:
                print(
                    f"    source={example['source']} "
                    f"length={example['length']} "
                    f"query={example['query']}"
                )

        if details["high_entropy_examples"]:
            print("  High-entropy examples:")
            for example in details["high_entropy_examples"]:
                print(
                    f"    source={example['source']} "
                    f"entropy={example['entropy']:.3f} "
                    f"length={example['length']} "
                    f"query={example['query']}"
                )


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Flag DNS-tunneling indicators in a PCAP."
    )
    parser.add_argument("pcap", help="Path to a PCAP or PCAPNG capture")
    parser.add_argument(
        "--long-label",
        type=int,
        default=40,
        help="Minimum label length to flag (default: 40)",
    )
    parser.add_argument(
        "--volume-threshold",
        type=int,
        default=100,
        help="Queries to one base domain required to flag it (default: 100)",
    )
    parser.add_argument(
        "--entropy-threshold",
        type=float,
        default=3.5,
        help="Minimum Shannon entropy in bits/character (default: 3.5)",
    )
    parser.add_argument(
        "--entropy-min-length",
        type=int,
        default=12,
        help="Minimum label length for entropy analysis (default: 12)",
    )
    parser.add_argument(
        "--suffix-labels",
        type=int,
        default=2,
        help="Final labels treated as the base domain (default: 2)",
    )
    parser.add_argument(
        "--max-examples",
        type=int,
        default=5,
        help="Maximum examples retained per indicator/domain (default: 5)",
    )
    return parser.parse_args()


def main() -> None:
    args = parse_args()

    if args.suffix_labels < 1:
        raise SystemExit("--suffix-labels must be at least 1")

    try:
        total, volumes, flagged = analyze_capture(
            capture_path=args.pcap,
            long_label_threshold=args.long_label,
            volume_threshold=args.volume_threshold,
            entropy_threshold=args.entropy_threshold,
            entropy_min_length=args.entropy_min_length,
            suffix_labels=args.suffix_labels,
            max_examples=args.max_examples,
        )
    except (OSError, ValueError) as error:
        raise SystemExit(f"Unable to analyze capture: {error}") from error

    print_report(total, volumes, flagged)


if __name__ == "__main__":
    main()
```

