    print(f"Base domains observed: {len(domain_volumes)}")
    print(f"Base domains flagged:  {len(flagged)}")

    if not flagged:
        print("\nNo indicators exceeded the configured thresholds.")
        return

    for domain, details in sorted(
        flagged.items(),
        key=lambda item: item[1]["query_count"],
        reverse=True,
    ):
        print(f"\n[FLAGGED] {domain}")

        for reason in details["reasons"]:
            print(f"  Reason: {reason}")

        top_sources = details["sources"].most_common(5)
        if top_sources:
            sources = ", ".join(
                f"{source} ({count})" for source, count in top_sources
            )
            print(f"  Top sources: {sources}")

        if details["long_label_examples"]:
            print("  Long-label examples:")
            for example in details["long_label_examples"]:
                print(
                    f"    source={example['source']} "
                    f"length={example['length']} "
                    f"query={example['query']}"
                )

        if details["high_entropy_examples"]:
            print("  High-entropy examples:")
            for example in details["high_entropy_examples"]:
                print(
                    f"    source={example['source']} "
                    f"entropy={example['entropy']:.3f} "
                    f"length={example['length']} "
                    f"query={example['query']}"
                )


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Flag DNS-tunneling indicators in a PCAP."
    )
    parser.add_argument("pcap", help="Path to a PCAP or PCAPNG capture")
    parser.add_argument(
        "--long-label",
        type=int,
        default=40,
        help="Minimum label length to flag (default: 40)",
    )
    parser.add_argument(
        "--volume-threshold",
        type=int,
        default=100,
        help="Queries to one base domain required to flag it (default: 100)",
    )
    parser.add_argument(
        "--entropy-threshold",
        type=float,
        default=3.5,
        help="Minimum Shannon entropy in bits/character (default: 3.5)",
    )
    parser.add_argument(
        "--entropy-min-length",
        type=int,
        default=12,
        help="Minimum label length for entropy analysis (default: 12)",
    )
    parser.add_argument(
        "--suffix-labels",
        type=int,
        default=2,
        help="Final labels treated as the base domain (default: 2)",
    )
    parser.add_argument(
        "--max-examples",
        type=int,
        default=5,
        help="Maximum examples retained per indicator/domain (default: 5)",
    )
    return parser.parse_args()


def main() -> None:
    args = parse_args()

    if args.suffix_labels < 1:
        raise SystemExit("--suffix-labels must be at least 1")

    try:
        total, volumes, flagged = analyze_capture(
            capture_path=args.pcap,
            long_label_threshold=args.long_label,
            volume_threshold=args.volume_threshold,
            entropy_threshold=args.entropy_threshold,
            entropy_min_length=args.entropy_min_length,
            suffix_labels=args.suffix_labels,
            max_examples=args.max_examples,
        )
    except (OSError, ValueError) as error:
        raise SystemExit(f"Unable to analyze capture: {error}") from error

    print_report(total, volumes, flagged)


if __name__ == "__main__":
    main()
```

